import json, sys, pytest
class Probe:
    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_call(self, item):
        page = item.funcargs['page']
        page.on('pageerror', lambda error: print('PAGEERROR', str(error)))
        def response(r):
            if '/v1/escola/' in r.url:
                try: data = r.json()
                except Exception: data = 'non-JSON response'
                print('SCHOOL_RESPONSE', json.dumps({'url':r.url,'status':r.status,'body':data}, ensure_ascii=False))
        page.on('response', response)
        yield
        print('DESK_MESSAGE', repr(page.locator('#deskMsg').inner_text()))
        page.screenshot(path=str(item.funcargs['evidence_dir'] / 'v9-escola-diagnostic.png'))
raise SystemExit(pytest.main(sys.argv[1:], plugins=[Probe()]))
